from collections import deque

blocks = ["block1", "block2"]
goal = {("ontable", "block1"), ("ontable", "block2")}

initial = {
    ("ontable", "block1"),
    ("holding", "block2"),
    ("clear", "block1"),
}

def applicable(state):
    actions = []

    for x in blocks:
        if ("ontable", x) in state and ("clear", x) in state and ("handempty",) in state:
            actions.append((f"pickup {x}", "pickup", (x,)))

    for x in blocks:
        if ("holding", x) in state:
            actions.append((f"putdown {x}", "putdown", (x,)))

    for x in blocks:
        for y in blocks:
            if x != y and ("holding", x) in state and ("clear", y) in state:
                actions.append((f"stack {x} {y}", "stack", (x, y)))

    for x in blocks:
        for y in blocks:
            if (
                x != y
                and ("on", x, y) in state
                and ("clear", x) in state
                and ("handempty",) in state
            ):
                actions.append((f"unstack {x} {y}", "unstack", (x, y)))

    return actions

def apply_action(state, kind, args):
    s = set(state)

    if kind == "pickup":
        x = args[0]
        s.remove(("ontable", x))
        s.remove(("clear", x))
        s.remove(("handempty",))
        s.add(("holding", x))

    elif kind == "putdown":
        x = args[0]
        s.remove(("holding", x))
        s.add(("ontable", x))
        s.add(("clear", x))
        s.add(("handempty",))

    elif kind == "stack":
        x, y = args
        s.remove(("holding", x))
        s.remove(("clear", y))
        s.add(("on", x, y))
        s.add(("clear", x))
        s.add(("handempty",))

    elif kind == "unstack":
        x, y = args
        s.remove(("on", x, y))
        s.remove(("clear", x))
        s.remove(("handempty",))
        s.add(("holding", x))
        s.add(("clear", y))

    return frozenset(s)

start = frozenset(initial)
queue = deque([(start, [])])
visited = {start}
found = False

while queue:
    state, plan = queue.popleft()

    if goal.issubset(state):
        for action in plan:
            print(f"({action})")
        found = True
        break

    for description, kind, args in applicable(state):
        next_state = apply_action(state, kind, args)
        if next_state not in visited:
            visited.add(next_state)
            queue.append((next_state, plan + [description]))

if not found:
    print("No plan")

from collections import deque

initial_stacks = [
    (7,),
    (2, 1, 5),
    (12, 13),
    (11, 14),
    (3,),
    (6, 8, 10, 4),
    (9,)
]

goal_stacks = [
    (10, 3),
    (8, 6),
    (4,),
    (13, 7),
    (11, 1, 9, 14, 12, 2, 5)
]

MAX_STACKS = 3

def canon(stacks):
    return tuple(sorted(tuple(s) for s in stacks if s))

def is_goal(stacks, held):
    return held is None and canon(stacks) == canon(goal_stacks)

def stack_count(stacks):
    return len(stacks)

def get_successors(stacks, held):
    stacks = list(stacks)
    result = []

    if held is not None:
        new_stacks = list(stacks)
        new_stacks.append((held,))
        result.append((canon(new_stacks), None, f"(putdown block{held})"))

        for i, s in enumerate(stacks):
            if not s:
                continue
            y = s[0]
            new_stacks = []
            for j, t in enumerate(stacks):
                if j == i:
                    new_stacks.append((held,) + t)
                else:
                    new_stacks.append(t)
            result.append((canon(new_stacks), None, f"(stack block{held} block{y})"))
    else:
        for i, s in enumerate(stacks):
            if len(s) == 1:
                x = s[0]
                new_stacks = [t for j, t in enumerate(stacks) if j != i]
                result.append((canon(new_stacks), x, f"(pickup block{x})"))

        for i, s in enumerate(stacks):
            if len(s) >= 2:
                x = s[0]
                y = s[1]
                new_stacks = []
                for j, t in enumerate(stacks):
                    if j == i:
                        new_stacks.append(s[1:])
                    else:
                        new_stacks.append(t)
                result.append((canon(new_stacks), x, f"(unstack block{x} block{y})"))

    return result

start_stacks = canon(initial_stacks)
start = (start_stacks, None)

queue = deque([start])
visited = {start}
parent = {start: (None, None)}
solution = None

while queue:
    state = queue.popleft()
    stacks, held = state

    if is_goal(stacks, held):
        actions = []
        cur = state
        while parent[cur][0] is not None:
            prev, action = parent[cur]
            actions.append(action)
            cur = prev
        actions.reverse()
        solution = actions
        break

    for new_stacks, new_held, action in get_successors(stacks, held):
        if stack_count(new_stacks) > MAX_STACKS:
            continue

        next_state = (new_stacks, new_held)
        if next_state not in visited:
            visited.add(next_state)
            parent[next_state] = (state, action)
            queue.append(next_state)

if solution is None:
    print("No plan")
else:
    for action in solution:
        print(action)

