from collections import deque

N = 10

start_pos = [0] * N
start_pos[0] = 10   # block1 on block10
start_pos[1] = 1    # block2 on block1
start_pos[8] = 6    # block9 on block6

start = (tuple(start_pos), -1, 0)


def is_clear(pos, held, b):
    for v in pos:
        if v == b + 1:
            return False
    if held == b:
        return False
    return True


def is_goal(pos, held):
    if held != -1:
        return False
    if pos[0] != 8:  # block1 on block8
        return False
    for i in range(1, N):
        if pos[i] != 0:
            return False
    return True


def next_states(state):
    pos_tuple, held, locked = state
    pos = list(pos_tuple)

    if held == -1:
        for x in range(N):
            if pos[x] > 0:
                y = pos[x] - 1
                if is_clear(pos, held, x):
                    np = pos.copy()
                    np[x] = -1
                    yield (tuple(np), x, locked), ("unstack", x, y)

        for x in range(N):
            if pos[x] == 0 and not (locked & (1 << x)):
                if is_clear(pos, held, x):
                    np = pos.copy()
                    np[x] = -1
                    yield (tuple(np), x, locked), ("pickup", x)

    else:
        x = held

        np = pos.copy()
        np[x] = 0
        yield (tuple(np), -1, locked | (1 << x)), ("putdown", x)

        for y in range(N):
            if y != x and is_clear(pos, held, y):
                np = pos.copy()
                np[x] = y + 1
                yield (tuple(np), -1, locked), ("stack", x, y)


def format_action(action):
    name = action[0]
    if name in ("pickup", "putdown"):
        return f"({name} block{action[1] + 1})"
    return f"({name} block{action[1] + 1} block{action[2] + 1})"


def main():
    queue = deque([start])
    parent = {start: (None, None)}
    goal_state = None

    while queue:
        state = queue.popleft()
        pos, held, locked = state

        if is_goal(pos, held):
            goal_state = state
            break

        for new_state, action in next_states(state):
            if new_state not in parent:
                parent[new_state] = (state, action)
                queue.append(new_state)

    if goal_state is None:
        print("No plan")
        return

    actions = []
    current = goal_state

    while parent[current][0] is not None:
        previous, action = parent[current]
        actions.append(action)
        current = previous

    actions.reverse()

    for action in actions:
        print(format_action(action))


if __name__ == "__main__":
    main()

