import sys

N = 14
on = [None] * (N + 1)
holding = 0
plan = []

# Initial configuration
on[1] = 0
on[2] = 6
on[3] = 0
on[4] = 1
on[5] = 8
on[6] = 0
on[7] = 0
on[8] = 0
on[9] = 10
on[10] = 14
on[11] = 4
on[12] = 13
on[13] = 11
on[14] = 0


def is_clear(x):
    if x == holding:
        return True
    for b in range(1, N + 1):
        if on[b] == x:
            return False
    return True


def pickup(x):
    global holding
    if holding != 0 or on[x] != 0 or not is_clear(x):
        raise RuntimeError("invalid pickup")
    on[x] = None
    holding = x
    plan.append(("pickup", x))


def putdown(x):
    global holding
    if holding != x:
        raise RuntimeError("invalid putdown")
    on[x] = 0
    holding = 0
    plan.append(("putdown", x))


def unstack(x, y):
    global holding
    if holding != 0 or on[x] != y or not is_clear(x):
        raise RuntimeError("invalid unstack")
    on[x] = None
    holding = x
    plan.append(("unstack", x, y))


def stack(x, y):
    global holding
    if holding != x or x == y or not is_clear(y):
        raise RuntimeError("invalid stack")
    on[x] = y
    holding = 0
    plan.append(("stack", x, y))


def clear_above(x):
    while True:
        y = None
        for b in range(1, N + 1):
            if on[b] == x:
                y = b
                break
        if y is None:
            break
        clear_above(y)
        unstack(y, x)
        putdown(y)


def move_to_goal(k):
    target = 0 if k == 1 else k - 1

    if on[k] == target:
        clear_above(k)
        return

    clear_above(k)

    if on[k] == 0:
        pickup(k)
    else:
        support = on[k]
        unstack(k, support)

    if target == 0:
        putdown(k)
    else:
        stack(k, target)


for block in range(1, N + 1):
    move_to_goal(block)

# Verification
if holding != 0:
    raise RuntimeError("arm not empty")
if on[1] != 0:
    raise RuntimeError("block1 not on table")
for i in range(2, N + 1):
    if on[i] != i - 1:
        raise RuntimeError("goal not reached")

for action in plan:
    if action[0] in ("stack", "unstack"):
        _, x, y = action
        sys.stdout.write(f"({action[0]} block{x} block{y})\n")
    else:
        _, x = action
        sys.stdout.write(f"({action[0]} block{x})\n")

import itertools

def main():
    blocks = list(range(1, 15))
    goal_on = {
        1: 9,
        2: 0,
        3: 13,
        4: 7,
        5: 0,
        6: 0,
        7: 0,
        8: 0,
        9: 0,
        10: 5,
        11: 2,
        12: 11,
        13: 12,
        14: 6,
    }

    edges = [(x, goal_on[x]) for x in blocks if goal_on[x] != 0]

    for perm in itertools.permutations(edges):
        index = {x: i for i, (x, y) in enumerate(perm)}
        ok = True

        for i, (x, y) in enumerate(perm):
            if goal_on[y] != 0:
                if index[y] > i:
                    ok = False
                    break

        if not ok:
            continue

        for i, (x, y) in enumerate(perm):
            if x == 1:
                if i + 1 >= len(perm) or perm[i + 1][0] not in (2, 3):
                    ok = False
                    break

        if not ok:
            continue

        actions = []
        for x, y in perm:
            actions.append(f"(pickup block{x})")
            actions.append(f"(stack block{x} block{y})")

        print("\n".join(actions))
        return

    print("No plan")

if __name__ == "__main__":
    main()

import sys
import heapq

n = 14

initial_sup = [0] * (n + 1)
initial_sup[8] = 12
initial_sup[14] = 3

def make_additional_goal():
    sup = [0] * (n + 1)
    stacks = [
        [3, 6, 9, 12],
        [1, 5, 7, 11, 13],
        [2, 4, 8, 10, 14],
    ]
    for stack in stacks:
        prev = 0
        for b in stack:
            sup[b] = prev
            prev = b
    return sup

additional_sup = make_additional_goal()

def original_goal_ok(sup, held):
    if held != 0:
        return False
    for b in [1, 10, 4, 9, 8, 6, 13, 14, 12, 11, 3, 2]:
        if sup[b] != 0:
            return False
    if sup[7] != 6:
        return False
    if sup[5] != 0:
        return False
    return True

if not original_goal_ok(additional_sup, 0):
    print("No plan")
    sys.exit()

def clear(sup, held, x):
    if held == x:
        return False
    for b in range(1, n + 1):
        if sup[b] == x:
            return False
    return True

def apply_action(state, action):
    sup_tuple, held = state
    sup = [0] + list(sup_tuple)
    typ, x, y = action

    if typ == 0:
        if held == 0 and sup[x] == 0 and clear(sup, held, x):
            sup[x] = -1
            return (tuple(sup[1:]), x)

    elif typ == 1:
        if held == x:
            sup[x] = 0
            return (tuple(sup[1:]), 0)

    elif typ == 2:
        if held == 0 and sup[x] == y and clear(sup, held, x):
            sup[x] = -1
            return (tuple(sup[1:]), x)

    elif typ == 3:
        if held == x and x != y and sup[x] == -1 and clear(sup, held, y):
            sup[x] = y
            return (tuple(sup[1:]), 0)

    return None

def successors(state):
    sup_tuple, held = state
    sup = [0] + list(sup_tuple)

    if held == 0:
        for x in range(1, n + 1):
            if sup[x] == 0 and clear(sup, held, x):
                ns = apply_action(state, (0, x, 0))
                if ns is not None:
                    yield ns, f"(pickup block{x})"

            for y in range(1, n + 1):
                if sup[x] == y and clear(sup, held, x):
                    ns = apply_action(state, (2, x, y))
                    if ns is not None:
                        yield ns, f"(unstack block{x} block{y})"
    else:
        x = held
        ns = apply_action(state, (1, x, 0))
        if ns is not None:
            yield ns, f"(putdown block{x})"

        for y in range(1, n + 1):
            if y != x and clear(sup, held, y):
                ns = apply_action(state, (3, x, y))
                if ns is not None:
                    yield ns, f"(stack block{x} block{y})"

def heuristic(state, goal_tuple):
    sup_tuple, held = state
    h = 0
    for i in range(n):
        if sup_tuple[i] != goal_tuple[i]:
            h += 1
    if held != 0:
        h += 1
    return h

def solve(initial_state, goal_tuple):
    if initial_state[0] == goal_tuple and initial_state[1] == 0:
        return []

    pq = []
    heapq.heappush(pq, (heuristic(initial_state, goal_tuple), 0, initial_state, []))
    best = {initial_state: 0}

    while pq:
        f, g, state, path = heapq.heappop(pq)

        if g != best.get(state):
            continue

        if state[0] == goal_tuple and state[1] == 0:
            return path

        for ns, label in successors(state):
            ng = g + 1
            if ng < best.get(ns, 10**9):
                best[ns] = ng
                new_path = path + [label]
                heapq.heappush(
                    pq,
                    (ng + heuristic(ns, goal_tuple), ng, ns, new_path)
                )

    return None

initial_state = (tuple(initial_sup[1:]), 0)
goal_tuple = tuple(additional_sup[1:])

plan = solve(initial_state, goal_tuple)

if plan is None:
    print("No plan")
else:
    for line in plan:
        print(line)

def main():
