    for action in plan:
        if not valid:
            break
        if action[0] == 'pickup':
            _, b = action
            if holding != 0:
                valid = False
            if parent[b] != -1:
                valid = False
            if not is_clear(b, parent, holding):
                valid = False
            if valid:
                holding = b
                parent[b] = -2
                if b == 1:
