from collections import deque

def main():
    N = 7
    initial_pos = (0, 6, 0, 0, 0, 0, 0, 4)
    goal_pos = (0, 0, 0, 5, 0, 0, 4, 6)

    start = (initial_pos, 0, False)
    queue = deque([(start, ())])
    visited = {start}

    def clear(pos, x):
        for c in range(1, N + 1):
            if pos[c] == x:
                return False
        return True

    while queue:
        (pos, holding, need_five), path = queue.popleft()

        if pos == goal_pos and holding == 0 and not need_five:
            for action in path:
                print(action)
            return

        if holding == 0:
            for x in range(1, N + 1):
                if pos[x] == 0 and clear(pos, x):
                    if need_five and x % 5 != 0:
                        continue
                    new_pos = list(pos)
                    new_pos[x] = -1
                    state = (tuple(new_pos), x, x % 3 == 0)
                    if state not in visited:
                        visited.add(state)
                        queue.append((state, path + (f"(pickup block{x})",)))

            for x in range(1, N + 1):
                y = pos[x]
                if y != 0 and y != -1 and clear(pos, x):
                    if need_five and x % 5 != 0:
                        continue
                    new_pos = list(pos)
                    new_pos[x] = -1
                    state = (tuple(new_pos), x, x % 3 == 0)
                    if state not in visited:
                        visited.add(state)
                        queue.append((state, path + (f"(unstack block{x} block{y})",)))

        else:
            x = holding

            if not (need_five and x % 5 != 0):
                new_pos = list(pos)
                new_pos[x] = 0
                state = (tuple(new_pos), 0, x % 3 == 0)
                if state not in visited:
                    visited.add(state)
                    queue.append((state, path + (f"(putdown block{x})",)))

            if not (need_five and x % 5 != 0):
                for y in range(1, N + 1):
                    if y != x and pos[y] != -1 and clear(pos, y):
                        new_pos = list(pos)
