from collections import deque

pow10 = [10 ** i for i in range(8)]

def encode(pos):
    state = 0
    for i, p in enumerate(pos):
        d = 9 if p == -1 else p
        state += d * pow10[i]
    return state

initial = encode([0, 0, 0, 6, 1, 2, 5, 7])
goal = encode([0, 0, 0, 0, 0, 5, 0, 0])

parent = {initial: (None, None)}
queue = deque([initial])
found = False

while queue:
    state = queue.popleft()

    if state == goal:
        found = True
        break

    digits = [(state // p) % 10 for p in pow10]

    held = None
    for i, d in enumerate(digits):
        if d == 9:
            held = i
            break

    if held is None:
        for i, d in enumerate(digits):
            block_num = i + 1
            if block_num in digits:
                continue

            if d == 0:
                ns = state + (9 - d) * pow10[i]
                if ns not in parent:
                    parent[ns] = (state, 10000 + block_num * 100)
                    queue.append(ns)
            elif d > 0:
                ns = state + (9 - d) * pow10[i]
                if ns not in parent:
                    parent[ns] = (state, 30000 + block_num * 100 + d)
                    queue.append(ns)
    else:
        x = held
        x_num = x + 1

        ns = state + (0 - 9) * pow10[x]
        if ns not in parent:
            parent[ns] = (state, 20000 + x_num * 100)
            queue.append(ns)

        for j, _ in enumerate(digits):
            if j == x:
                continue

            target_num = j + 1
            if target_num in digits:
                continue

            ns = state + (target_num - 9) * pow10[x]
            if ns not in parent:
                parent[ns] = (state, 40000 + x_num * 100 + target_num)
                queue.append(ns)

if not found:
    print("No plan")
else:
    actions = []
    cur = goal

    while parent[cur][0] is not None:
        prev, code = parent[cur]
        t = code // 10000
        rem = code % 10000
        a = rem // 100
        b = rem % 100

        if t == 1:
            actions.append(f"(pickup block{a})")
        elif t == 2:
            actions.append(f"(putdown block{a})")
        elif t == 3:
            actions.append(f"(unstack block{a} block{b})")
        elif t == 4:
            actions.append(f"(stack block{a} block{b})")

        cur = prev

    actions.reverse()

    for action in actions:
        print(action)

