import heapq

n = 8
names = [chr(ord('a') + i) for i in range(n)]

init_pos = (-1, 0, -1, -1, 3, 4, -1, 6)
goal_pos = (-1, 0, 1, -1, 3, 4, -1, 6)


def clear(pos, i):
    for j in range(n):
        if pos[j] == i:
            return False
    return True


def heuristic(pos):
    return sum(1 for i in range(n) if pos[i] != goal_pos[i])


def actions(state):
    held, pos = state

    if held == -1:
        for i in range(n):
            if pos[i] == -1 and clear(pos, i):
                new_pos = list(pos)
                new_pos[i] = -2
                yield (i, tuple(new_pos)), ('pickup', i)

        for x in range(n):
            if pos[x] >= 0:
                y = pos[x]
                if clear(pos, x):
                    new_pos = list(pos)
                    new_pos[x] = -2
                    yield (x, tuple(new_pos)), ('unstack', x, y)

    else:
        i = held

        new_pos = list(pos)
        new_pos[i] = -1
        yield (-1, tuple(new_pos)), ('putdown', i)

        for y in range(n):
            if y != i and clear(pos, y):
                new_pos = list(pos)
                new_pos[i] = y
                yield (-1, tuple(new_pos)), ('stack', i, y)


def solve():
    start = (-1, init_pos)
    goal = (-1, goal_pos)

    open_heap = []
    counter = 0
    h0 = heuristic(init_pos)
    heapq.heappush(open_heap, (h0, 0, counter, start))
    counter += 1

    g_score = {start: 0}
    came_from = {}

    while open_heap:
        f, g, _, state = heapq.heappop(open_heap)

        if g != g_score.get(state, 10**9):
            continue

        if state == goal:
            actions_list = []
            cur = goal

            while cur in came_from:
                prev, act = came_from[cur]
                actions_list.append(act)
                cur = prev

            actions_list.reverse()

            for act in actions_list:
                if act[0] == 'pickup':
                    print(f"(pickup {names[act[1]]})")
                elif act[0] == 'putdown':
                    print(f"(putdown {names[act[1]]})")
                elif act[0] == 'stack':
                    print(f"(stack {names[act[1]]} {names[act[2]]})")
                elif act[0] == 'unstack':
                    print(f"(unstack {names[act[1]]} {names[act[2]]})")
            return

        for next_state, act in actions(state):
            new_g = g + 1

            if new_g < g_score.get(next_state, 10**9):
                g_score[next_state] = new_g
                h = heuristic(next_state[1])
                came_from[next_state] = (state, act)
                heapq.heappush(open_heap, (new_g + h, new_g, counter, next_state))
                counter += 1

    print("No plan")


if __name__ == "__main__":
    solve()

