from collections import deque

def normalize(stacks):
    return tuple(sorted(tuple(s) for s in stacks if s))

def find_plan():
    initial = normalize([
        ("block6", "block3", "block5"),
        ("block11",),
        ("block14", "block8", "block7", "block9", "block4", "block15",
         "block12", "block2", "block13", "block10"),
        ("block1",)
    ])

    goal = normalize([
        ("block8", "block7", "block12", "block5", "block13"),
        ("block15", "block4"),
        ("block3", "block11", "block2", "block9", "block14", "block10",
         "block6", "block1")
    ])

    required = 4

    if len(goal) != required:
        return None

    start = (None, initial)
    q = deque([start])
    parent = {start: (None, None)}

    while q:
        hold, stacks = q.popleft()

        if hold is None and stacks == goal:
            actions = []
            cur = (hold, stacks)
            while parent[cur][0] is not None:
                actions.append(parent[cur][1])
                cur = parent[cur][0]
            actions.reverse()
            return actions

        if hold is None:
            for i, s in enumerate(stacks):
                x = s[-1]

                if len(s) == 1:
                    new_stacks = list(stacks)
                    del new_stacks[i]
                    new_stacks = normalize(new_stacks)

                    if len(new_stacks) == required:
                        new_state = (x, new_stacks)
                        if new_state not in parent:
                            parent[new_state] = ((hold, stacks), f"(pickup {x})")
                            q.append(new_state)

                if len(s) >= 2:
                    y = s[-2]
                    new_stacks = list(stacks)
                    new_stacks[i] = s[:-1]
                    new_stacks = normalize(new_stacks)

                    if len(new_stacks) == required:
                        new_state = (x, new_stacks)
                        if new_state not in parent:
                            parent[new_state] = ((hold, stacks), f"(unstack {x} {y})")
                            q.append(new_state)

        else:
            x = hold

            new_stacks = normalize(list(stacks) + [(x,)])
            if len(new_stacks) == required:
                new_state = (None, new_stacks)
                if new_state not in parent:
                    parent[new_state] = ((hold, stacks), f"(putdown {x})")
                    q.append(new_state)

            for i, s in enumerate(stacks):
                y = s[-1]
                new_stacks = list(stacks)
                new_stacks[i] = s + (x,)
                new_stacks = normalize(new_stacks)

                if len(new_stacks) == required:
                    new_state = (None, new_stacks)
                    if new_state not in parent:
                        parent[new_state] = ((hold, stacks), f"(stack {x} {y})")
                        q.append(new_state)

    return None


def main():
    plan = find_plan()
    if plan is None:
        print("No plan")
    else:
        for action in plan:
            print(action)


