    main()

class BlocksworldSolver:
    def __init__(self, initial_on):
        self.blocks = list(range(1, 14))
        self.on = dict(initial_on)
        self.holding = None
        self.plan = []

    def is_clear(self, block):
        for x in self.blocks:
            if self.on[x] == block:
                return False
        return True

    def top_above(self, block):
        child = None
        for x in self.blocks:
            if self.on[x] == block:
                child = x
                break
        if child is None:
            raise ValueError("block is clear")
        while True:
            nxt = None
            for x in self.blocks:
                if self.on[x] == child:
                    nxt = x
                    break
            if nxt is None:
                return child
            child = nxt

    def do_unstack(self, x, y):
        assert self.holding is None
        assert self.on[x] == y
        assert self.is_clear(x)
        self.plan.append(("unstack", x, y))
        self.on[x] = -1
        self.holding = x

    def do_putdown(self, x):
        assert self.holding == x
        assert self.on[x] == -1
        self.plan.append(("putdown", x))
        self.on[x] = 0
        self.holding = None

    def do_pickup(self, x):
        assert self.holding is None
        assert self.on[x] == 0
        assert self.is_clear(x)
        self.plan.append(("pickup", x))
        self.on[x] = -1
        self.holding = x

    def do_stack(self, x, y):
        assert self.holding == x
        assert x != y
        assert self.is_clear(y)
        self.plan.append(("stack", x, y))
        self.on[x] = y
        self.holding = None

    def ensure_clear(self, block):
        assert self.holding is None
        while not self.is_clear(block):
            top = self.top_above(block)
            support = self.on[top]
            assert support > 0
            self.do_unstack(top, support)
            self.do_putdown(top)

    def move_to_table(self, x):
        self.ensure_clear(x)
        if self.on[x] == 0:
            return
        support = self.on[x]
        assert support > 0
        self.do_unstack(x, support)
        self.do_putdown(x)

    def move_onto(self, x, y):
        self.ensure_clear(x)

        if self.on[x] == y:
            return

        self.ensure_clear(y)

        if self.on[x] == y:
            return

        if self.on[x] == 0:
            self.do_pickup(x)
        else:
            support = self.on[x]
            assert support > 0
            self.do_unstack(x, support)

        self.do_stack(x, y)

    def matches_goal(self, goal_on):
        if self.holding is not None:
            return False
        for b in self.blocks:
            if self.on[b] != goal_on[b]:
                return False
        return True

    def format_action(self, action):
        if action[0] == "pickup":
            return f"(pickup block{action[1]})"
        if action[0] == "putdown":
            return f"(putdown block{action[1]})"
        if action[0] in ("stack", "unstack"):
            return f"({action[0]} block{action[1]} block{action[2]})"
        raise ValueError("unknown action")

    def print_plan(self):
        for action in self.plan:
            print(self.format_action(action))


