from collections import deque

def solve():
    labels = ['a', 'b', 'c', 'd', 'e']
    n = 5
    TABLE = 5
    HELD = -1

    # Initial state from the two required starting towers:
    # a on table, c on a, e on c
    # b on table, d on b
    start_on = [TABLE, TABLE, 0, 1, 2]  # a, b, c, d, e
    start = (tuple(start_on), -1)

    # Goal: a on b, b on c, c on d, d on e, e on table
    goal_on = [1, 2, 3, 4, TABLE]
    goal = (tuple(goal_on), -1)

    def is_clear(on, held, x):
        if held == x:
            return False
        for y in range(n):
            if on[y] == x:
                return False
        return True

    def successors(state):
        on, held = state
        out = []

        if held == -1:
            for x in range(n):
                y = on[x]
                if y != TABLE and y != HELD and is_clear(on, held, x):
                    new_on = list(on)
                    new_on[x] = HELD
                    out.append((('unstack', labels[x], labels[y]), (tuple(new_on), x)))

            for x in range(n):
                if on[x] == TABLE and is_clear(on, held, x):
                    new_on = list(on)
                    new_on[x] = HELD
                    out.append((('pickup', labels[x]), (tuple(new_on), x)))
        else:
            x = held

            new_on = list(on)
            new_on[x] = TABLE
            out.append((('putdown', labels[x]), (tuple(new_on), -1)))

            for y in range(n):
                if y != x and is_clear(on, held, y):
                    new_on = list(on)
                    new_on[x] = y
                    out.append((('stack', labels[x], labels[y]), (tuple(new_on), -1)))

        return out

    queue = deque([start])
    parent = {start: (None, None)}

    while queue:
        state = queue.popleft()
        if state == goal:
            break

        for action, next_state in successors(state):
            if next_state not in parent:
                parent[next_state] = (state, action)
                queue.append(next_state)

    if goal not in parent:
        print("No plan")
        return

    plan = []
    state = goal
    while state != start:
        prev_state, action = parent[state]
        plan.append(action)
        state = prev_state

    plan.reverse()

    for action in plan:
        print("(" + " ".join(action) + ")")

