    ((1, 4, 6, 10, 11, 12), (2, 3, 5, 7, 8, 9)),
    ((1, 4, 5, 6, 7, 10), (2, 3, 8, 9, 11, 12)),
    ((3, 4, 7, 8, 9, 10), (1, 2, 5, 6, 11, 12)),
