    ((2, 4, 5, 6, 7, 8, 10), (1, 3, 9, 11, 12)),
    ((1, 4, 6, 7, 8, 10, 11), (2, 3, 5, 9, 12)),
    ((1, 2, 5, 6, 7, 8, 10), (3, 4, 9, 11, 12)),
]

def build_pdb(group):
    gset = set(group)
    goal_abs = tuple(goal[x] if goal[x] in gset else 0 for x in group)
    dist = {goal_abs: 0}
    q = deque([goal_abs])

    while q:
        st = q.popleft()
        d = dist[st] + 1
        has_child = set()
        for v in st:
            if v != 0:
                has_child.add(v)

        clears = []
        for i, x in enumerate(group):
            if x not in has_child:
                clears.append(i)

        for i in clears:
            x = group[i]
            source = st[i]

            if source != 0:
                nxt = list(st)
                nxt[i] = 0
                nxt = tuple(nxt)
                if nxt not in dist:
                    dist[nxt] = d
                    q.append(nxt)

            for j in clears:
                y = group[j]
                if y == x:
                    continue
                if y == source:
                    continue

                nxt = list(st)
                nxt[i] = y
                nxt = tuple(nxt)
                if nxt not in dist:
                    dist[nxt] = d
                    q.append(nxt)

    return dist

unique_groups = []
seen_groups = set()
for part in partitions:
    for g in part:
        if g not in seen_groups:
            seen_groups.add(g)
            unique_groups.append(g)

pdb_info = {}
for g in unique_groups:
    pdb_info[g] = (set(g), build_pdb(g))

heuristic_cache = {}

def heuristic(st):
    if st in heuristic_cache:
        return heuristic_cache[st]

    keep = [False] * (n + 1)

    for b in range(1, n + 1):
        c = b
        ok = True
        seen_chain = set()

        while c != 0:
            if c in seen_chain:
                ok = False
                break
            seen_chain.add(c)

            if st[c] != goal[c]:
                ok = False
                break

            c = st[c]

        keep[b] = ok

    lower = 0
    for b in range(1, n + 1):
        if not keep[b]:
            if st[b] == goal[b]:
                lower += 2
            else:
                lower += 1

    best = 0

    for part in partitions:
        total = 0

        for g in part:
            gset, dist = pdb_info[g]
            proj = tuple(st[x] if st[x] in gset else 0 for x in g)
            total += dist.get(proj, 0)

        if total > best:
            best = total

    if lower > best:
        best = lower

    heuristic_cache[st] = best
    return best

def successors(st):
    has_child = [False] * (n + 1)

    for i in range(1, n + 1):
        p = st[i]
        if p != 0:
            has_child[p] = True

    clear = [i for i in range(1, n + 1) if not has_child[i]]

    for x in clear:
        source = st[x]

        if source != 0:
            nxt = list(st)
            nxt[x] = 0
            yield tuple(nxt), (x, 0)

        for y in clear:
            if y == x:
                continue
            if y == source:
                continue

            nxt = list(st)
            nxt[x] = y
            yield tuple(nxt), (x, y)

def solve():
    start = init
    target = goal

    if start == target:
        return []

    gscore = {start: 0}
    came_from = {}

    h0 = heuristic(start)
    heap = []
    counter = 0

    heapq.heappush(heap, (h0, 0, counter, 0, start))

    while heap:
        f, neg_g, _, g, st = heapq.heappop(heap)

        if g != gscore.get(st):
            continue

        if st == target:
            moves_rev = []
            cur = target

            while cur != start:
                prev, act = came_from[cur]
                moves_rev.append((prev, act))
                cur = prev

            moves_rev.reverse()

            lines = []

            for prev, act in moves_rev:
                x, dest = act
                src = prev[x]

                if src == 0:
                    lines.append("(pickup block%d)" % x)
                else:
                    lines.append("(unstack block%d block%d)" % (x, src))

                if dest == 0:
                    lines.append("(putdown block%d)" % x)
                else:
                    lines.append("(stack block%d block%d)" % (x, dest))

            return lines

        for nxt, act in successors(st):
            ng = g + 1

            if nxt not in gscore or ng < gscore[nxt]:
