initial = bytes([1, 8, 2, 9, 3, 6, 10, 7, 1])
goal = bytes([5, 4, 1, 1, 1, 1, 6, 1, 9])


def successors(state):
    held = -1
    for i, v in enumerate(state):
        if v == 0:
            held = i
            break

    clear = [True] * N
    for v in state:
        if v > 1:
            clear[v - 2] = False

    result = []

    if held == -1:
        for i, v in enumerate(state):
            if v == 1 and clear[i]:
                ns = bytearray(state)
                ns[i] = 0
                result.append((("pickup", i + 1), bytes(ns)))

        for i, v in enumerate(state):
            if v > 1 and clear[i]:
                y = v - 1
                ns = bytearray(state)
                ns[i] = 0
                result.append((("unstack", i + 1, y), bytes(ns)))
    else:
        i = held
        ns = bytearray(state)
        ns[i] = 1
        result.append((("putdown", i + 1), bytes(ns)))

        for j, v in enumerate(state):
            if j == i:
                continue
            if v == 0:
                continue
            if clear[j]:
                ns = bytearray(state)
                ns[i] = j + 2
                result.append((("stack", i + 1, j + 1), bytes(ns)))

    return result


def inverse(action):
    kind = action[0]
    if kind == "pickup":
        return ("putdown", action[1])
    if kind == "putdown":
        return ("pickup", action[1])
    if kind == "unstack":
        return ("stack", action[1], action[2])
    if kind == "stack":
        return ("unstack", action[1], action[2])
    raise ValueError


def reconstruct(meet, parent_start, parent_goal):
    start_rev = []
    s = meet
    while parent_start[s][0] is not None:
        prev, action = parent_start[s]
        start_rev.append(action)
        s = prev
    start_actions = list(reversed(start_rev))

    goal_actions = []
    s = meet
    while parent_goal[s][0] is not None:
        prev, action_to_prev = parent_goal[s]
        goal_actions.append(action_to_prev)
        s = prev

    return start_actions + goal_actions


def format_action(action):
    kind = action[0]
    if kind in ("pickup", "putdown"):
        return f"({kind} block{action[1]})"
    return f"({kind} block{action[1]} block{action[2]})"


def solve():
    if initial == goal:
        return []

    front_start = {initial}
    front_goal = {goal}

    parent_start = {initial: (None, None)}
    parent_goal = {goal: (None, None)}

    while front_start and front_goal:
        if len(front_start) <= len(front_goal):
            new_front = set()
            for current in front_start:
                for action, nxt in successors(current):
                    if nxt in parent_start:
                        continue
                    parent_start[nxt] = (current, action)
                    if nxt in parent_goal:
                        return reconstruct(nxt, parent_start, parent_goal)
                    new_front.add(nxt)
            front_start = new_front
        else:
            new_front = set()
            for current in front_goal:
                for action, nxt in successors(current):
                    if nxt in parent_goal:
                        continue
                    parent_goal[nxt] = (current, inverse(action))
                    if nxt in parent_start:
                        return reconstruct(nxt, parent_start, parent_goal)
                    new_front.add(nxt)
            front_goal = new_front

    return None


plan = solve()

if plan is None:
    print("No plan")
elif plan:
    print("\n".join(format_action(action) for action in plan))

