)))

goal_stacks = tuple(sorted((
    (7, 3),
    (8, 13),
    (5, 2, 1),
    (10,),
    (11,),
    (6,),
    (4,),
    (9,),
    (12,),
)))


def make_support(stacks):
    supp = {}
    for s in stacks:
        below = 0
        for b in s:
            supp[b] = below
            below = b
    return supp


def compute_settled(stacks):
    supp = make_support(stacks)
    memo = {}

    def rec(b):
        if b in memo:
            return memo[b]
        cur = supp.get(b, None)
        if cur != goal_support[b]:
            memo[b] = False
        elif goal_support[b] == 0:
            memo[b] = True
        else:
            memo[b] = rec(goal_support[b])
        return memo[b]

    return supp, rec


def heuristic(stacks, held, cache):
    key = (stacks, held)
    if key in cache:
        return cache[key]

    supp, rec = compute_settled(stacks)
    count = 0
    for b in range(1, N + 1):
        if b == held:
            continue
        if not rec(b):
            count += 1

    cache[key] = count
    return count


def successors(stacks, held, pruned):
    if held == 0:
        if pruned:
            supp, rec = compute_settled(stacks)

        for i, s in enumerate(stacks):
            x = s[-1]
            if pruned and rec(x):
                continue

            if len(s) == 1:
                new_stacks = list(stacks)
                del new_stacks[i]
                new_stacks = tuple(sorted(new_stacks))
                yield (new_stacks, x), "(pickup " + block_name[x] + ")", 1
            else:
                y = s[-2]
                new_stacks = list(stacks)
                new_stacks[i] = s[:-1]
                new_stacks = tuple(sorted(new_stacks))
                yield (new_stacks, x), "(unstack " + block_name[x] + " " + block_name[y] + ")", 1
    else:
        x = held

        new_stacks = list(stacks)
        new_stacks.append((x,))
        new_stacks = tuple(sorted(new_stacks))
        yield (new_stacks, 0), "(putdown " + block_name[x] + ")", 0

        if pruned:
            supp, rec = compute_settled(stacks)
            target = goal_support[x]
            if target != 0:
                for i, s in enumerate(stacks):
                    y = s[-1]
                    if y == target and rec(y):
                        new_stacks = list(stacks)
                        new_stacks[i] = s + (x,)
                        new_stacks = tuple(sorted(new_stacks))
                        yield (new_stacks, 0), "(stack " + block_name[x] + " " + block_name[y] + ")", 0
                        break
        else:
            for i, s in enumerate(stacks):
                y = s[-1]
                new_stacks = list(stacks)
                new_stacks[i] = s + (x,)
                new_stacks = tuple(sorted(new_stacks))
                yield (new_stacks, 0), "(stack " + block_name[x] + " " + block_name[y] + ")", 0


def solve(pruned):
    start = (initial_stacks, 0)
    goal = (goal_stacks, 0)

    h_cache = {}
    start_h = heuristic(initial_stacks, 0, h_cache)

    heap = []
    counter = 0
    best = {start: (0, 0)}
    parent = {start: (None, None)}

    heapq.heappush(heap, (start_h, 0, start_h, 0, counter, start))

    while heap:
        f, g, h, pickups, _, state = heapq.heappop(heap)

        if best.get(state) != (pickups, g):
            continue

        stacks, held = state

        if held == 0 and stacks == goal_stacks:
            actions = []
            cur = state
            while parent[cur][0] is not None:
                prev, action = parent[cur]
                actions.append(action)
                cur = prev
            actions.reverse()

            if actions:
                print("\n".join(actions))
            return True

        for (new_stacks, new_held), action, pickup_increment in successors(stacks, held, pruned):
            new_pickups = pickups + pickup_increment
            if new_pickups > 20:
                continue

            new_g = g + 1
            new_state = (new_stacks, new_held)
            old = best.get(new_state)

            if old is None or new_pickups < old[0] or (new_pickups == old[0] and new_g < old[1]):
                best[new_state] = (new_pickups, new_g)
                parent[new_state] = (state, action)

                new_h = heuristic(new_stacks, new_held, h_cache)
                counter += 1
                heapq.heappush(
                    heap,
                    (new_pickups + new_h, new_g, new_h, new_pickups, counter, new_state)
                )

    return False


