                candidates.append((("pickup", top), normalize(new_stacks), top))

            if len(s) >= 2:
                below = s[-2]
                new_stacks = stacks.copy()
                new_stacks[i] = s[:-1]
                candidates.append((("unstack", top, below), normalize(new_stacks), top))
    else:
        x = holding

        new_stacks = stacks + [(x,)]
        candidates.append((("putdown", x), normalize(new_stacks), 0))

        for i, s in enumerate(stacks):
            if not s:
