            y = s[-1]
            new_stacks = stacks.copy()
            new_stacks[i] = s + (x,)
            candidates.append((("stack", x, y), normalize(new_stacks), 0))

    for action, new_stacks, new_holding in candidates:
        if all(len(s) <= 2 for s in new_stacks):
