import heapq
from functools import lru_cache

def solve_blocksworld():
    n = 10

    initial_parent = [-1] * n
    initial_parent[7] = 4
    initial_hand = -1
    start = (tuple(initial_parent), initial_hand)

    goal_parent = [-1] * n
    goal_parent[0] = 4
    goal_parent[1] = -1
    goal_parent[2] = 1
    goal_parent[3] = 9
    goal_parent[4] = 2
    goal_parent[5] = -1
    goal_parent[6] = 0
    goal_parent[7] = 6
    goal_parent[8] = 5
    goal_parent[9] = 8
    goal_tuple = tuple(goal_parent)

    def is_goal(state):
        par, hand = state
        return hand == -1 and par == goal_tuple

    @lru_cache(maxsize=None)
    def heuristic(state):
        par, hand = state
        fixed = [False] * n
        changed = True
        while changed:
            changed = False
            for b in range(n):
                if fixed[b]:
                    continue
                if par[b] == goal_parent[b]:
                    gp = goal_parent[b]
                    if gp == -1:
                        fixed[b] = True
                        changed = True
                    elif fixed[gp]:
                        fixed[b] = True
                        changed = True
        nonfixed = sum(1 for f in fixed if not f)
        if hand == -1:
            return 2 * nonfixed
        else:
            return 2 * (nonfixed - 1) + 1

    def get_actions(state):
        par, hand = state
        par_list = list(par)
        clear = [True] * n
        for p in par:
            if p >= 0:
                clear[p] = False

        actions = []
        if hand == -1:
            for x in range(n):
                if par[x] == -1 and clear[x]:
                    new_par = par_list.copy()
                    new_par[x] = -2
                    actions.append(((tuple(new_par), x), ('pickup', x, None)))
            for x in range(n):
                y = par[x]
                if y >= 0 and clear[x]:
                    new_par = par_list.copy()
                    new_par[x] = -2
                    actions.append(((tuple(new_par), x), ('unstack', x, y)))
        else:
            x = hand
            new_par = par_list.copy()
            new_par[x] = -1
            actions.append(((tuple(new_par), -1), ('putdown', x, None)))
            for y in range(n):
                if y != x and par[y] != -2 and clear[y]:
                    new_par = par_list.copy()
                    new_par[x] = y
                    actions.append(((tuple(new_par), -1), ('stack', x, y)))
        return actions

    def reconstruct(came_from, state):
        actions = []
        while state in came_from:
            prev, act = came_from[state]
            actions.append(act)
            state = prev
        actions.reverse()
        return actions

    def format_action(act):
        name, x, y = act
        if name == 'pickup':
            return f"(pickup block{x + 1})"
        elif name == 'putdown':
            return f"(putdown block{x + 1})"
        elif name == 'stack':
            return f"(stack block{x + 1} block{y + 1})"
        elif name == 'unstack':
            return f"(unstack block{x + 1} block{y + 1})"

    open_heap = []
    counter = 0
    h0 = heuristic(start)
    heapq.heappush(open_heap, (h0, 0, counter, start))
    g_score = {start: 0}
    came_from = {}
    closed = set()

    while open_heap:
        f, g, _, state = heapq.heappop(open_heap)
        if state in closed:
            continue
        if g != g_score.get(state, 10**9):
            continue
        if is_goal(state):
            plan = reconstruct(came_from, state)
            if plan:
                for act in plan:
                    print(format_action(act))
            return
        closed.add(state)
        for next_state, act in get_actions(state):
            new_g = g + 1
            if next_state in closed:
                continue
            if new_g < g_score.get(next_state, 10**9):
                g_score[next_state] = new_g
                came_from[next_state] = (state, act)
                h = heuristic(next_state)
                counter += 1
                heapq.heappush(open_heap, (new_g + h, new_g, counter, next_state))
    print("No plan")

