        if on[b] == x:
            return False
    return True

def above_weight(b, on, seen):
    total = 0
    for x in range(1, N + 1):
        if on[x] == b:
            if x in seen:
                return 10**9
            total += x + above_weight(x, on, seen | {x})
    return total

def valid_weight(on):
    for b in range(1, N + 1):
        if above_weight(b, on, {b}) > b:
            return False
    return True

def solve(initial, goal):
    if not valid_weight(goal):
        return None

    start = (tuple(initial), 0)
    goal_state = (tuple(goal), 0)

    if start == goal_state:
        return []

    q = deque([start])
    parent = {start: (None, None)}

    while q:
        state = q.popleft()
        on, held = state

        if state == goal_state:
            actions = []
            while parent[state][0] is not None:
                prev, action = parent[state]
                actions.append(action)
                state = prev
            actions.reverse()
            return actions

        if held == 0:
            for x in range(1, N + 1):
                if on[x] == 0 and clear(x, on):
                    new_on = list(on)
                    new_on[x] = -1
                    ns = (tuple(new_on), x)
                    if ns not in parent and valid_weight(ns[0]):
                        parent[ns] = (state, f"(pickup block{x})")
                        q.append(ns)

                if on[x] > 0 and clear(x, on):
                    y = on[x]
                    new_on = list(on)
                    new_on[x] = -1
                    ns = (tuple(new_on), x)
                    if ns not in parent and valid_weight(ns[0]):
                        parent[ns] = (state, f"(unstack block{x} block{y})")
                        q.append(ns)
        else:
            x = held

            new_on = list(on)
            new_on[x] = 0
            ns = (tuple(new_on), 0)
            if ns not in parent and valid_weight(ns[0]):
                parent[ns] = (state, f"(putdown block{x})")
                q.append(ns)

            for y in range(1, N + 1):
                if y != x and on[y] != -1 and clear(y, on):
                    new_on = list(on)
                    new_on[x] = y
                    ns = (tuple(new_on), 0)
                    if ns not in parent and valid_weight(ns[0]):
                        parent[ns] = (state, f"(stack block{x} block{y})")
                        q.append(ns)

    return None

