class BlocksWorld:
    def __init__(self, below, held):
        self.below = dict(below)
        self.held = held
        self.plan = []

    def is_clear(self, x):
        if x == self.held:
            return False
        return all(v != x for v in self.below.values())

    def pickup(self, x):
        if self.held is not None:
            raise ValueError("hand not empty")
        if self.below[x] != -1:
            raise ValueError("block not on table")
        if not self.is_clear(x):
            raise ValueError("block not clear")
        self.below[x] = None
        self.held = x
        self.plan.append(f"(pickup {x})")

    def putdown(self, x):
        if self.held != x:
            raise ValueError("block not held")
        self.below[x] = -1
        self.held = None
        self.plan.append(f"(putdown {x})")

    def unstack(self, x, y):
        if self.held is not None:
            raise ValueError("hand not empty")
        if self.below[x] != y:
            raise ValueError("block not on support")
        if not self.is_clear(x):
            raise ValueError("block not clear")
        self.below[x] = None
        self.held = x
        self.plan.append(f"(unstack {x} {y})")

    def stack(self, x, y):
        if self.held != x:
            raise ValueError("block not held")
        if x == y:
            raise ValueError("cannot stack on itself")
        if not self.is_clear(y):
            raise ValueError("support not clear")
        self.below[x] = y
        self.held = None
        self.plan.append(f"(stack {x} {y})")


