import heapq

def canon(towers):
    return tuple(sorted(tuple(t) for t in towers))

def heuristic(state):
    h = 0
    for tower in state:
        L = len(tower)
        for i, b in enumerate(tower):
            if b == 14:
                if not (L == 2 and tower[0] == 3 and i == 1):
                    h += 1
            elif b == 3:
                if not (i == 0 and (L == 1 or (L == 2 and tower[1] == 14))):
                    h += 1
            else:
                if not (L == 1 and i == 0):
                    h += 1
    return h

def make_actions(x, source_under, dest_y):
    a = []
    if source_under is None:
        a.append(f"(pickup block{x})")
    else:
        a.append(f"(unstack block{x} block{source_under})")
    if dest_y is None:
        a.append(f"(putdown block{x})")
    else:
        a.append(f"(stack block{x} block{dest_y})")
    return tuple(a)

def successors(state):
    moves = []
    n = len(state)
    for i in range(n):
        tower = state[i]
        x = tower[-1]
        source_under = None if len(tower) == 1 else tower[-2]
        remaining = tower[:-1]

        if len(tower) > 1:
            new_towers = []
            for k, t in enumerate(state):
                if k == i:
                    if remaining:
                        new_towers.append(remaining)
                else:
                    new_towers.append(t)
            new_towers.append((x,))
            ns = canon(new_towers)
            moves.append((ns, make_actions(x, source_under, None)))

        for j, t2 in enumerate(state):
            if j == i:
                continue
            y = t2[-1]
            new_towers = []
            for k, t in enumerate(state):
                if k == i:
                    if remaining:
                        new_towers.append(remaining)
                elif k == j:
                    new_towers.append(t + (x,))
                else:
                    new_towers.append(t)
            ns = canon(new_towers)
            moves.append((ns, make_actions(x, source_under, y)))
    return moves

