    if start == goal:
        return []

    start_h = heuristic(start)
    heap = []
    counter = 0
    heapq.heappush(heap, (start_h, start_h, counter, start, 0))
    best_g = {start: 0}
    parent = {}

    while heap:
        f, h, cnt, state, g = heapq.heappop(heap)
        if best_g.get(state) != g:
            continue

        if state == goal:
