def main():
    n = 9
    blocks = range(1, n + 1)
    initial_stacks = tuple(sorted((i,) for i in blocks))
    goal_chain = (8, 3, 6, 5, 2, 1, 9, 4, 7)
    goal_stacks = (goal_chain,)
    source = 1
    target = 2
    window = 4

    def has_direct_above(stacks, upper, lower):
        for st in stacks:
            for i in range(len(st) - 1):
                if st[i] == lower and st[i + 1] == upper:
                    return True
        return False

    if (not has_direct_above(initial_stacks, source, target)) and has_direct_above(goal_stacks, source, target):
        print("No plan")
        return

    def canonical(stacks):
        return tuple(sorted(tuple(st) for st in stacks if st))

    def get_actions(stacks, held):
        actions = []
        if held is None:
            for idx, st in enumerate(stacks):
                top = st[-1]
                if len(st) == 1:
                    new_stacks = list(stacks)
                    new_stacks.pop(idx)
                    actions.append((f"(pickup block{top})", top, canonical(new_stacks), None))
                else:
                    below = st[-2]
                    new_stacks = list(stacks)
                    new_stacks[idx] = st[:-1]
                    actions.append((f"(unstack block{top} block{below})", top, canonical(new_stacks), top))
        else:
            h = held
            new_stacks = list(stacks) + [(h,)]
            actions.append((f"(putdown block{h})", h, canonical(new_stacks), None))
            for idx, st in enumerate(stacks):
                top = st[-1]
                if top == h:
                    continue
                new_stacks = list(stacks)
                new_stacks[idx] = st + (h,)
                actions.append((f"(stack block{h} block{top})", h, canonical(new_stacks), None))
        return actions

    def update_pending(pending, moved):
        if moved == target:
            return None
        if pending is None:
            if moved == source:
                return window
            return None
        if pending <= 1:
            return "invalid"
        new_pending = pending - 1
        if moved == source:
            new_pending = min(new_pending, window)
        return new_pending

    start = (initial_stacks, None, None)
    goal_state = (goal_stacks, None, None)

    queue = deque([start])
    visited = {start}
    parent = {start: (None, None)}

    while queue:
        state = queue.popleft()
        stacks, held, pending = state

        if state == goal_state:
            plan = []
            current = state
            while parent[current][0] is not None:
                previous, action = parent[current]
                plan.append(action)
                current = previous
            plan.reverse()
            print("\n".join(plan))
            return

        for action, moved, new_stacks, new_held in get_actions(stacks, held):
            new_pending = update_pending(pending, moved)
            if new_pending == "invalid":
                continue
            next_state = (new_stacks, new_held, new_pending)
            if next_state not in visited:
                visited.add(next_state)
                parent[next_state] = (state, action)
                queue.append(next_state)

    print("No plan")

