def solve():
    n = 7

    start_pos = [0] * (n + 1)
    start_pos[5] = 0
    start_pos[4] = 5
    start_pos[1] = 4
    start_pos[2] = 1
    start_pos[6] = 0
    start_pos[7] = 6
    start_pos[3] = 7
    start = (0, tuple(start_pos))

    goal_pos = [0] * (n + 1)
    goal_pos[1] = 5
    goal_pos[2] = 0
    goal_pos[3] = 0
    goal_pos[4] = 7
    goal_pos[5] = 2
    goal_pos[6] = 3
    goal_pos[7] = 1
    goal = (0, tuple(goal_pos))

    def successors(state):
        holding, pos = state

        supported = [False] * (n + 1)
        for b in range(1, n + 1):
            p = pos[b]
            if p > 0:
                supported[p] = True

        if holding == 0:
            for x in range(1, n + 1):
                if pos[x] == 0 and not supported[x]:
                    new_pos = list(pos)
                    new_pos[x] = -1
                    yield (x, tuple(new_pos)), ("pickup", x)

            for x in range(1, n + 1):
                if pos[x] > 0 and not supported[x]:
                    y = pos[x]
                    new_pos = list(pos)
                    new_pos[x] = -1
                    yield (x, tuple(new_pos)), ("unstack", x, y)
        else:
            x = holding

            new_pos = list(pos)
            new_pos[x] = 0
            yield (0, tuple(new_pos)), ("putdown", x)

            for y in range(1, n + 1):
                if y != x and not supported[y]:
                    new_pos = list(pos)
                    new_pos[x] = y
                    yield (0, tuple(new_pos)), ("stack", x, y)

    queue = deque([start])
    parent = {start: (None, None)}
    found = False

    while queue:
        state = queue.popleft()

        if state == goal:
            found = True
            break

        for next_state, action in successors(state):
            if next_state not in parent:
                parent[next_state] = (state, action)
                queue.append(next_state)

    if not found:
        print("No plan")
        return

    plan = []
    current = goal
    while current != start:
        previous, action = parent[current]
        plan.append(action)
        current = previous

