n = 10

goal_loc_list = [0] * (n + 1)
goal_loc_list[1] = 0
goal_loc_list[2] = 9
goal_loc_list[3] = 0
goal_loc_list[4] = 0
goal_loc_list[5] = 0
goal_loc_list[6] = 5
goal_loc_list[7] = 6
goal_loc_list[8] = 4
goal_loc_list[9] = 3
goal_loc_list[10] = 1
goal_loc = tuple(goal_loc_list)

