initial_state = (initial_loc, 0, 0)
goal_state = (goal_loc, 0, 0)


def is_clear(loc, block):
    if block == 0:
        return True
    for i in range(1, n + 1):
        if loc[i] == block:
            return False
    return True


def next_required(block):
    if block == 2:
        return 4
    if block == 4:
        return 6
    return 0


def heuristic(state):
    loc, holding, pending = state
    cost = 0
    correct = 0

    for b in range(1, n + 1):
        if b == holding:
            cost += 1
        else:
            if loc[b] != goal_loc[b]:
                cost += 2
            else:
                correct += 1

    if pending != 0:
        if holding != pending:
            if loc[pending] == goal_loc[pending]:
                cost += 2

    block2_done = (
        holding != 2
        and loc[2] == goal_loc[2]
        and loc[9] == goal_loc[9]
        and pending == 0
    )

    if not block2_done and pending == 0:
        for support in (4, 6):
            for b in range(1, n + 1):
                if b == support:
                    continue
                if loc[b] == support and goal_loc[b] == support:
                    cost += 2

    return cost, correct


def successors(state):
    loc, holding, pending = state

    if holding == 0:
        for x in range(1, n + 1):
            if pending != 0 and x != pending:
                continue
            if loc[x] == -1:
                continue
            if not is_clear(loc, x):
                continue

            temp_list = list(loc)
            temp_list[x] = -1
            temp_loc = tuple(temp_list)

            req = next_required(x)
            if req != 0 and not is_clear(temp_loc, req):
                continue

            if loc[x] == 0:
                yield (temp_loc, x, pending), f"pickup block{x}"
            else:
                y = loc[x]
                yield (temp_loc, x, pending), f"unstack block{x} block{y}"

    else:
        x = holding

        if pending != 0 and pending != x:
            return

        req = next_required(x)
        new_pending = req

        new_list = list(loc)
        new_list[x] = 0
        new_loc = tuple(new_list)

        if new_pending == 0 or is_clear(new_loc, new_pending):
            yield (new_loc, 0, new_pending), f"putdown block{x}"

        for y in range(1, n + 1):
            if y == x:
                continue
            if loc[y] == -1:
                continue
            if not is_clear(loc, y):
                continue

            new_list = list(loc)
            new_list[x] = y
            new_loc = tuple(new_list)

            if new_pending == 0 or is_clear(new_loc, new_pending):
                yield (new_loc, 0, new_pending), f"stack block{x} block{y}"


start = initial_state
