goal = (0, 0, 0, 0, 0, 0, 2, 0, 0, 9, 0, 0, 7, 0)

def is_clear(state, block):
    for v in state:
        if v == block:
            return False
    return True

def heuristic(state):
    h = 0
    for a, b in zip(state, goal):
        if a != b:
            h += 1 if a == -1 else 2
    return h

def successors(state):
    result = []
    held = 0
    for i, v in enumerate(state):
        if v == -1:
            held = i + 1
            break

    if held:
        ns = list(state)
        ns[held - 1] = 0
        result.append((f"putdown block{held}", tuple(ns)))

        for y in range(1, n + 1):
            if y == held:
                continue
            if state[y - 1] == -1:
                continue
            if is_clear(state, y):
                ns = list(state)
                ns[held - 1] = y
                result.append((f"stack block{held} block{y}", tuple(ns)))
    else:
        for x in range(1, n + 1):
            if state[x - 1] == 0 and is_clear(state, x):
                ns = list(state)
                ns[x - 1] = -1
                result.append((f"pickup block{x}", tuple(ns)))

            if state[x - 1] > 0 and is_clear(state, x):
                y = state[x - 1]
                ns = list(state)
                ns[x - 1] = -1
                result.append((f"unstack block{x} block{y}", tuple(ns)))

    return result

def solve():
    start = initial
    if start == goal:
        return []

    pq = []
    counter = 0
    heapq.heappush(pq, (heuristic(start), 0, counter, start, ()))
    counter += 1

    best = {start: 0}

    while pq:
        f, g, _, state, path = heapq.heappop(pq)

        if g != best.get(state):
            continue

        if state == goal:
            return list(path)

        for action, ns in successors(state):
            ng = g + 1
            if ng < best.get(ns, 10**9):
                best[ns] = ng
                npath = path + (action,)
                heapq.heappush(pq, (ng + heuristic(ns), ng, counter, ns, npath))
                counter += 1

    return None

