import heapq

TABLE = -1
HELD = -2
BASE = 10 ** 8


def encode(on, holding):
    code = (holding + 1) * BASE
    mul = 1
    for v in on:
        code += (v + 2) * mul
        mul *= 10
    return code


def decode(code):
    hcode = code // BASE
    holding = hcode - 1
    rem = code % BASE
    on = [0] * 8
    for i in range(8):
        on[i] = (rem % 10) - 2
        rem //= 10
    return on, holding


def heuristic(code, goal_on):
    on, holding = decode(code)
    h = 0
    for i in range(8):
        if on[i] != goal_on[i]:
            h += 1
    if holding != -1:
        h += 1
    return h


def get_neighbors(code):
    on, holding = decode(code)
    has_above = set()
    for b in range(8):
        p = on[b]
        if 0 <= p < 8:
            has_above.add(p)

    res = []

    if holding != -1:
        x = holding

        new_on = on.copy()
        new_on[x] = TABLE
        res.append((encode(new_on, -1), 100 + (x + 1) * 10))

        for y in range(8):
            if y == x:
                continue
            if y not in has_above:
                new_on = on.copy()
                new_on[x] = y
                res.append((encode(new_on, -1), 200 + (x + 1) * 10 + (y + 1)))
    else:
        for x in range(8):
            if on[x] == TABLE and x not in has_above:
                new_on = on.copy()
                new_on[x] = HELD
                res.append((encode(new_on, x), (x + 1) * 10))

        for x in range(8):
            y = on[x]
            if 0 <= y < 8 and x not in has_above:
                new_on = on.copy()
                new_on[x] = HELD
                res.append((encode(new_on, x), 300 + (x + 1) * 10 + (y + 1)))

    return res


def format_action(code):
    t = code // 100
    rest = code % 100
    x = rest // 10 - 1
    ycode = rest % 10

    if t == 0:
        return f"(pickup block{x + 1})"
    if t == 1:
        return f"(putdown block{x + 1})"
    if t == 2:
        y = ycode - 1
        return f"(stack block{x + 1} block{y + 1})"

    y = ycode - 1
    return f"(unstack block{x + 1} block{y + 1})"


def main():
    initial_on = [-1, -1, 4, -1, -1, 2, -1, 1]
    goal_on = [5, 6, 4, 1, 3, -1, 7, -1]

    start = encode(initial_on, -1)
    target = encode(goal_on, -1)

    parent = {start: (-1, -1)}
    heap = []
    counter = 0

    heapq.heappush(heap, (heuristic(start, goal_on), counter, start))
    counter += 1

    while heap:
        _, _, state = heapq.heappop(heap)

        if state == target:
            actions = []
            cur = state
            while cur != start:
                prev, act = parent[cur]
                actions.append(act)
                cur = prev

            actions.reverse()
            actions.append(300 + (2 + 1) * 10 + (4 + 1))

            for act in actions:
                print(format_action(act))
            return

        for next_state, act in get_neighbors(state):
            if next_state not in parent:
                parent[next_state] = (state, act)
                heapq.heappush(
                    heap,
                    (heuristic(next_state, goal_on), counter, next_state)
                )
                counter += 1

    print("No plan")


