from collections import deque

def canonical(stacks, holding):
    return (tuple(sorted(stacks)), holding)

def get_actions(state):
    stacks, holding = state
    stacks = list(stacks)
    actions = []
    if holding is None:
        # unstack actions
        for i, stack in enumerate(stacks):
            if len(stack) >= 2:
                x = stack[-1]
                y = stack[-2]
                new_stacks = stacks.copy()
                new_stacks[i] = stack[:-1]
                actions.append((f"(unstack block{x} block{y})", canonical(new_stacks, x)))
        # pickup actions from table
        for i, stack in enumerate(stacks):
            if len(stack) == 1:
                x = stack[0]
                new_stacks = stacks.copy()
                del new_stacks[i]
                actions.append((f"(pickup block{x})", canonical(new_stacks, x)))
    else:
        x = holding
        # putdown
        new_stacks = stacks.copy()
        new_stacks.append((x,))
        actions.append((f"(putdown block{x})", canonical(new_stacks, None)))
        # stack on another block
        for i, stack in enumerate(stacks):
            y = stack[-1]
            new_stacks = stacks.copy()
            new_stacks[i] = stack + (x,)
            actions.append((f"(stack block{x} block{y})", canonical(new_stacks, None)))
    return actions

def is_goal(state):
    stacks, holding = state
    if holding is not None:
        return False
    return len(stacks) == 10 and all(len(s) == 1 for s in stacks)

def solve():
    initial_stacks = [
        (8, 4, 1, 2),
        (9,),
        (3, 6),
        (7,),
        (5, 10)
    ]
    initial = canonical(initial_stacks, None)
    goal = canonical(tuple((i,) for i in range(1, 11)), None)

    q = deque()
    q.append((initial, []))
    visited = set([initial])

    while q:
        state, path = q.popleft()
        if state == goal:
            return path

        for action_str, next_state in get_actions(state):
            if next_state in visited:
                continue
            stacks, holding = next_state
            # Additional constraint: after any move, exactly 10 stacks must exist.
            if len(stacks) != 10:
                continue
            visited.add(next_state)
            q.append((next_state, path + [action_str]))
    return None

