    }
    for b, below in initial.items():
        parent[b] = below

    goal = [0] * (n + 1)
    goal_relations = {
        8: 15,
        13: 8,
        14: 13,
        1: 14,
        2: 11,
        6: 4,
        12: 6,
        3: 12
    }
    for b, below in goal_relations.items():
        goal[b] = below

    actions = []

    def child_on(block):
        for i in range(1, n + 1):
            if parent[i] == block:
                return i
        return None

    def clear_above(block):
        c = child_on(block)
        while c is not None:
            clear_above(c)
            support = parent[c]
            if support != 0:
                actions.append(("unstack", c, support))
                actions.append(("putdown", c))
                parent[c] = 0
            c = child_on(block)

    def move_to_table(block):
        if parent[block] == 0:
            return
        clear_above(block)
        support = parent[block]
        if support != 0:
            actions.append(("unstack", block, support))
            actions.append(("putdown", block))
            parent[block] = 0

    def place_on(block, target):
        if parent[block] != 0:
            clear_above(block)
            support = parent[block]
            if support != 0:
                actions.append(("unstack", block, support))
                actions.append(("putdown", block))
                parent[block] = 0
        else:
            clear_above(block)

        clear_above(target)
        actions.append(("pickup", block))
        actions.append(("stack", block, target))
        parent[block] = target

    finalized = [False] * (n + 1)

    changed = True
    while changed:
        changed = False
        for b in range(1, n + 1):
            if not finalized[b] and parent[b] == goal[b]:
                p = goal[b]
                if p == 0 or finalized[p]:
                    finalized[b] = True
                    changed = True

    while not all(finalized[1:]):
        chosen = None
        for b in range(1, n + 1):
            if not finalized[b]:
                p = goal[b]
                if p == 0 or finalized[p]:
                    chosen = b
                    break

        if chosen is None:
            break

        x = chosen
        p = goal[x]

        if parent[x] == p:
            finalized[x] = True
        else:
            if p == 0:
                move_to_table(x)
            else:
                place_on(x, p)
            finalized[x] = True

    lines = []
    for action in actions:
        if action[0] == "pickup":
            lines.append(f"(pickup block{action[1]})")
        elif action[0] == "putdown":
            lines.append(f"(putdown block{action[1]})")
        elif action[0] == "unstack":
            lines.append(f"(unstack block{action[1]} block{action[2]})")
        elif action[0] == "stack":
            lines.append(f"(stack block{action[1]} block{action[2]})")

    print("\n".join(lines))


