from collections import deque

def solve():
    initial_table = (('block3',), ('block4',), ('block1',), ('block2',))
    initial = (initial_table, None)
    goal_table = (('block4',), ('block2',), ('block1',), ('block3',))
    goal = (goal_table, None)

    if initial == goal:
        return []

    queue = deque([initial])
    parent = {initial: (None, None)}

    while queue:
        state = queue.popleft()
        table, holding = state

        if holding is None:
            for i, stack in enumerate(table):
                if not stack:
                    continue
                top = stack[-1]
                if len(stack) == 1:
                    new_table = table[:i] + table[i+1:]
                    new_state = (new_table, top)
                    action = ('pickup', top)
                    if new_state not in parent:
                        parent[new_state] = (state, action)
                        if new_state == goal:
                            return reconstruct(parent, new_state)
                        queue.append(new_state)
                if len(stack) > 1:
                    below = stack[-2]
                    new_stack = stack[:-1]
                    new_table = table[:i] + (new_stack,) + table[i+1:]
                    new_state = (new_table, top)
                    action = ('unstack', top, below)
                    if new_state not in parent:
                        parent[new_state] = (state, action)
                        if new_state == goal:
                            return reconstruct(parent, new_state)
                        queue.append(new_state)
        else:
            X = holding
            new_table = table + ((X,),)
            new_state = (new_table, None)
            action = ('putdown', X)
            if new_state not in parent:
                parent[new_state] = (state, action)
                if new_state == goal:
                    return reconstruct(parent, new_state)
                queue.append(new_state)
            for i, stack in enumerate(table):
                if not stack:
                    continue
                Y = stack[-1]
                if Y == X:
                    continue
                new_stack = stack + (X,)
                new_table = table[:i] + (new_stack,) + table[i+1:]
                new_state = (new_table, None)
                action = ('stack', X, Y)
                if new_state not in parent:
                    parent[new_state] = (state, action)
                    if new_state == goal:
                        return reconstruct(parent, new_state)
                    queue.append(new_state)

    return None

def reconstruct(parent, state):
    actions = []
    while True:
        prev, action = parent[state]
        if action is None:
            break
        actions.append(action)
        state = prev
    actions.reverse()
    return actions

