goal_towers = ((blocks[3],), (blocks[1],), (blocks[0],), (blocks[2],))
start = (start_towers, None)
goal = (goal_towers, None)

def get_actions(state):
    towers, held = state
    actions = []
    if held is None:
        for i, t in enumerate(towers):
            if len(t) == 1:
                x = t[0]
                new_towers = towers[:i] + towers[i+1:]
                actions.append((f"(pickup {x})", (new_towers, x)))
        for i, t in enumerate(towers):
            if len(t) >= 2:
                x = t[-1]
                y = t[-2]
                new_t = t[:-1]
                new_towers = towers[:i] + (new_t,) + towers[i+1:]
                actions.append((f"(unstack {x} {y})", (new_towers, x)))
    else:
        x = held
        new_towers = towers + ((x,),)
        actions.append((f"(putdown {x})", (new_towers, None)))
        for i, t in enumerate(towers):
            y = t[-1]
            if weight[x] <= weight[y]:
                new_t = t + (x,)
                new_towers = towers[:i] + (new_t,) + towers[i+1:]
                actions.append((f"(stack {x} {y})", (new_towers, None)))
    return actions

