def main():
    blocks = [f"block{i}" for i in range(1, 16)]

    goal_stacks = [
        ["block11", "block7", "block13", "block1", "block5", "block14"],
        ["block15", "block8", "block2"],
        ["block6", "block3", "block9"],
        ["block10", "block12", "block4"],
    ]

    support_goal = {b: "table" for b in blocks}
    parent = {}

    for stack in goal_stacks:
        for i in range(1, len(stack)):
            child = stack[i]
            par = stack[i - 1]
            parent[child] = par
            support_goal[child] = par

    move_order = [
        "block3", "block9",
        "block12", "block4",
        "block7", "block13",
        "block8",
        "block1",
        "block2",
        "block5", "block14",
    ]

    plan = []
    for b in move_order:
        plan.append(("pickup", b))
        plan.append(("stack", b, parent[b]))

    support = {b: "table" for b in blocks}
    held = None

    def is_clear(b):
        return b not in support.values()

    ok = True

    for action in plan:
        if action[0] == "pickup":
            _, x = action
            if held is not None or support[x] != "table" or not is_clear(x):
                ok = False
                break
            support[x] = "held"
            held = x
        elif action[0] == "stack":
            _, x, y = action
            if held != x or x == y or not is_clear(y):
                ok = False
                break
            support[x] = y
            held = None
        else:
            ok = False
            break

    if held is not None:
        ok = False

    if support != support_goal:
        ok = False

    if ok:
        move_records = []
        for idx, action in enumerate(plan):
            if action[0] in ("pickup", "unstack", "putdown"):
                moved = action[1]
            else:
                moved = action[1]
            move_records.append((idx, moved))

        for idx, moved in move_records:
            if moved == "block1":
                if not any(j > idx and m == "block2" for j, m in move_records):
                    ok = False
                    break

    if not ok:
        print("No plan")
        return

    for action in plan:
        if len(action) == 2:
            print(f"({action[0]} {action[1]})")
        else:
            print(f"({action[0]} {action[1]} {action[2]})")


if __name__ == "__main__":
    main()

import sys
import heapq

N = 15
TABLE = N

gpar = [13, 10, 11, 15, 15, 3, 15, 14, 15, 15, 15, 5, 7, 12, 15]
initial = (-1, 15, 3, 15, 15, 15, 8, 15, 15, 15, 15, 15, 15, 15, 9)
goal = tuple(gpar)


def stable_array(pos):
    stable = [False] * N
    changed = True
    while changed:
        changed = False
        for i in range(N):
            if stable[i]:
                continue
            p = pos[i]
            if p == gpar[i]:
                if p == TABLE or (0 <= p < N and stable[p]):
                    stable[i] = True
                    changed = True
    return stable


def heuristic(pos):
    st = stable_array(pos)
    unstable = 0
    hand = -1
    for i, v in enumerate(pos):
        if not st[i]:
            unstable += 1
        if v == -1:
            hand = i
    h = 2 * unstable
    if hand != -1:
        h -= 1
    return max(0, h)


def neighbors(pos):
    st = stable_array(pos)
    covered = [False] * N
    for v in pos:
        if 0 <= v < N:
            covered[v] = True

    hand = -1
    try:
        hand = pos.index(-1)
    except ValueError:
        pass

    result = []

    if hand != -1:
        h = hand

        p = list(pos)
        p[h] = TABLE
        result.append((tuple(p), f"(putdown block{h + 1})"))

        target = gpar[h]
        if target != TABLE and target != h:
            y = target
            if pos[y] != -1 and not covered[y] and st[y]:
                p = list(pos)
                p[h] = y
                result.append((tuple(p), f"(stack block{h + 1} block{y + 1})"))
    else:
        for x in range(N):
            if st[x] or covered[x]:
                continue

            ppos = pos[x]
            if ppos == TABLE:
                p = list(pos)
                p[x] = -1
                result.append((tuple(p), f"(pickup block{x + 1})"))
            elif 0 <= ppos < N:
                p = list(pos)
                p[x] = -1
                result.append((tuple(p), f"(unstack block{x + 1} block{ppos + 1})"))

    return result


def main():
    start = initial
    heap = []
    counter = 0

    heapq.heappush(heap, (heuristic(start), 0, counter, start, ()))
    best = {start: 0}

    while heap:
        f, neg_g, _, pos, path = heapq.heappop(heap)
        g = -neg_g

        if best.get(pos) != g:
            continue

        if pos == goal:
            if path:
                sys.stdout.write("\n".join(path))
            return

        for npos, action in neighbors(pos):
            ng = g + 1
            old = best.get(npos)
            if old is None or ng < old:
                best[npos] = ng
                counter += 1
                heapq.heappush(
                    heap,
                    (ng + heuristic(npos), -ng, counter, npos, path + (action,))
                )

    sys.stdout.write("No plan")


if __name__ == "__main__":
    main()
